import pytest

def test_include_router_itself():
    router = APIRouter()
    try:
        router.include_router(router)
        print("Failed: router.include_router(router) did not raise error")
    except Exception as e:
        print(f"Caught expected error: {e}")

def test_include_app_itself():
    app = FastAPI()
    try:
        app.include_router(app)
        print("Failed: app.include_router(app) did not raise error")
    except Exception as e:
        print(f"Caught expected error: {e}")

if __name__ == "__main__":
    test_include_router_itself()
    test_include_app_itself()
